(window.WCD=window.WCD||[]).push(["expressions",[["Fexpr_une_fois",1,"belge","Une fois","E","« Une fois » est le tic de langage belge le plus célèbre (et le plus caricaturé) : « Viens une fois ici ! ». Il sert juste à adoucir ou à insister, sans parler d'une seule fois.",116,"https://fr.wiktionary.org/wiki/Une_fois","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-une-fois.webp"],["Fexpr_septante",2,"belge","Septante","R","« Septante » veut dire soixante-dix en Belgique (et en Suisse). Beaucoup plus logique que « soixante-dix », avouons-le.",null,"https://fr.wiktionary.org/wiki/Septante","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-septante.webp"],["Fexpr_nonante",3,"belge","Nonante","R","« Nonante » veut dire quatre-vingt-dix en Belgique et en Suisse. Par contre, quatre-vingts reste quatre-vingts en Belgique !",113,"https://fr.wiktionary.org/wiki/Nonante","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-nonante.webp"],["Fexpr_dikkenek",4,"belge","Dikkenek","R","Un « dikkenek » est un vantard qui parle fort, une grande gueule, en argot bruxellois. Le mot a été popularisé par le film culte Dikkenek (2006).",114,"https://fr.wiktionary.org/wiki/Dikkenek","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-dikkenek.webp"],["Fexpr_brol",5,"belge","Brol","PC","Le « brol », c'est le bazar, le désordre, ou un objet sans valeur : « Range un peu ton brol ! »",null,"https://fr.wiktionary.org/wiki/Brol","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-brol.webp"],["Fexpr_savoir_pour_pouvoir",6,"belge","Savoir (pour pouvoir)","PC","En Belgique, « savoir » remplace souvent « pouvoir » : « Je ne sais pas venir demain » veut dire qu'on ne peut pas venir, pas qu'on a oublié le chemin.",114,"https://fr.wiktionary.org/wiki/Savoir","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-savoir-pour-pouvoir.webp"],["Fexpr_kot",7,"belge","Kot","PC","Un « kot » est une chambre ou un logement d'étudiant en Belgique. Les étudiants « kotent » pendant l'année universitaire.",106,"https://fr.wiktionary.org/wiki/Kot","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-kot.webp"],["Fexpr_guindaille",8,"belge","Guindaille","PC","La « guindaille » est une fête étudiante (souvent très arrosée) en Belgique. Celui qui guindaille est un guindailleur.",null,"https://fr.wiktionary.org/wiki/Guindaille","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-guindaille.webp"],["Fexpr_drache",9,"belge","Drache","R","Une « drache » est une grosse averse, une pluie battante. La « drache nationale » tombe traditionnellement le 21 juillet, jour de la fête nationale belge.",112,"https://fr.wiktionary.org/wiki/Drache","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-drache.webp"],["Fexpr_baraki",10,"belge","Baraki","R","Un « baraki » est en Belgique l'équivalent du beauf : quelqu'un de vulgaire, souvent avec un goût prononcé pour le tuning et le training.",114,"https://fr.wiktionary.org/wiki/Baraki","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-baraki.webp"],["Fexpr_a_tantot",11,"belge","À tantôt","PC","« À tantôt » veut dire « à tout à l'heure » (plus tard dans la même journée) en Belgique.",null,"https://fr.wiktionary.org/wiki/À_tantôt","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-a-tantot.webp"],["Fexpr_diner_et_souper",12,"belge","Dîner et souper","PC","En Belgique, on déjeune le matin, on dîne à midi et on soupe le soir. Pratique pour se tromper d'heure avec des amis français.",116,"https://fr.wiktionary.org/wiki/Dîner_et_souper","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-diner-et-souper.webp"],["Fexpr_loque_a_reloqueter",13,"belge","Loque à reloqueter","R","La « loque à reloqueter » est une serpillière en Belgique (surtout en Wallonie). « Reloqueter », c'est laver le sol.",null,"https://fr.wiktionary.org/wiki/Loque_à_reloqueter","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-loque-a-reloqueter.webp"],["Fexpr_gsm",14,"belge","GSM","C","En Belgique, le téléphone portable s'appelle un « GSM », du nom de la norme de téléphonie mobile.",null,"https://fr.wiktionary.org/wiki/GSM","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-gsm.webp"],["Fexpr_il_fait_cru",15,"belge","Il fait cru","C","« Il fait cru » veut dire qu'il fait un froid humide qui pénètre jusqu'aux os, un temps typiquement belge.",null,"https://fr.wiktionary.org/wiki/Il_fait_cru","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-il-fait-cru.webp"],["Fexpr_zwanze",16,"belge","Zwanze","PC","La « zwanze » est l'humour bruxellois, moqueur et absurde, plein d'autodérision.",null,"https://fr.wiktionary.org/wiki/Zwanze","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-zwanze.webp"],["Fexpr_choser",17,"belge","Choser","C","« Choser » est un verbe passe-partout belge qui remplace n'importe quel verbe qu'on ne trouve pas : « Tu peux choser la porte ? »",116,"https://fr.wiktionary.org/wiki/Choser","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-choser.webp"],["Fexpr_sacoche",18,"belge","Sacoche","C","En Belgique, une « sacoche » est un sac à main, et pas seulement un sac de vélo.",null,"https://fr.wiktionary.org/wiki/Sacoche","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-sacoche.webp"],["Fexpr_blocus",19,"belge","Blocus","PC","Le « blocus » est la période où les étudiants belges s'enferment pour réviser avant les examens. On dit aussi « bloquer ».",111,"https://fr.wiktionary.org/wiki/Blocus","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-blocus.webp"],["Fexpr_ketje",20,"belge","Ketje","C","Un « ketje » est un gamin, un petit Bruxellois débrouillard et malicieux.",null,"https://fr.wiktionary.org/wiki/Ketje","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ketje.webp"],["Fexpr_pistolet",21,"belge","Pistolet","PC","Un « pistolet » est un petit pain rond et croustillant, star du dimanche matin en Belgique.",null,"https://fr.wiktionary.org/wiki/Pistolet","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-pistolet.webp"],["Fexpr_chicon",22,"belge","Chicon","PC","Le « chicon » est le nom belge de l'endive. Le plat national : les chicons au gratin.",null,"https://fr.wiktionary.org/wiki/Chicon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-chicon.webp"],["Fexpr_avoir_dur",23,"belge","Avoir dur","C","« Avoir dur » veut dire avoir du mal, avoir des difficultés : « J'ai dur de me lever le matin. »",null,"https://fr.wiktionary.org/wiki/Avoir_dur","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-dur.webp"],["Fexpr_s_il_vous_plait_voila",24,"belge","S'il vous plaît (voilà)","C","En Belgique, « s'il vous plaît » s'utilise aussi en tendant quelque chose, à la place de « voilà ».",null,"https://fr.wiktionary.org/wiki/S'il_vous_plaît","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-s-il-vous-plait-voila.webp"],["Fexpr_tirer_son_plan",25,"belge","Tirer son plan","C","« Tirer son plan » veut dire se débrouiller tout seul : « Je te laisse, tu vas bien tirer ton plan. »",null,"https://fr.wiktionary.org/wiki/Tirer_son_plan","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-tirer-son-plan.webp"],["Fexpr_clinche",26,"belge","Clinche","C","La « clinche » est la poignée de porte, en Belgique et dans le Nord de la France.",null,"https://fr.wiktionary.org/wiki/Clinche","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-clinche.webp"],["Fexpr_essuie",27,"belge","Essuie","C","Un « essuie » est une serviette (de bain ou de vaisselle) en Belgique.",null,"https://fr.wiktionary.org/wiki/Essuie","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-essuie.webp"],["Fexpr_aubette",28,"belge","Aubette","C","Une « aubette » est un abribus en Belgique, et aussi un kiosque à journaux.",null,"https://fr.wiktionary.org/wiki/Aubette","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-aubette.webp"],["Fexpr_tof",29,"belge","Tof","C","« Tof » veut dire chouette, super, génial en Belgique : « C'était vraiment tof ! »",null,"https://fr.wiktionary.org/wiki/Tof","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-tof.webp"],["Fexpr_carabistouille",30,"belge","Carabistouille","PC","Une « carabistouille » est une bêtise, une sornette : « Arrête de raconter des carabistouilles ! »",null,"https://fr.wiktionary.org/wiki/Carabistouille","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-carabistouille.webp"],["Fexpr_crolle",31,"belge","Crolle","C","Une « crolle » est une boucle de cheveux en Belgique. Quelqu'un qui a les cheveux bouclés est « crollé ».",null,"https://fr.wiktionary.org/wiki/Crolle","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-crolle.webp"],["Fexpr_avoir_une_brique_dans_le_ventre",32,"belge","Avoir une brique dans le ventre","PC","Les Belges ont « une brique dans le ventre » : ils rêvent tous de construire leur propre maison.",null,"https://fr.wiktionary.org/wiki/Avoir_une_brique_dans_le_ventre","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-une-brique-dans-le-ventre.webp"],["Fexpr_bonne_continuation",33,"belge","Bonne continuation","C","« Bonne continuation » est la formule belge pour souhaiter bonne suite à quelqu'un qu'on quitte.",null,"https://fr.wiktionary.org/wiki/Bonne_continuation","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-bonne-continuation.webp"],["Fexpr_avoir_le_cafard",34,"francaise","Avoir le cafard","C","« Avoir le cafard » veut dire être triste, déprimé. L'expression a été popularisée par Baudelaire.",null,"https://fr.wiktionary.org/wiki/Avoir_le_cafard","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-le-cafard.webp"],["Fexpr_poser_un_lapin",35,"francaise","Poser un lapin","PC","« Poser un lapin » à quelqu'un, c'est ne pas venir à un rendez-vous sans prévenir.",null,"https://fr.wiktionary.org/wiki/Poser_un_lapin","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-poser-un-lapin.webp"],["Fexpr_couter_un_bras",36,"francaise","Coûter un bras","C","« Coûter un bras » veut dire coûter extrêmement cher.",null,"https://fr.wiktionary.org/wiki/Coûter_un_bras","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-couter-un-bras.webp"],["Fexpr_tomber_dans_les_pommes",37,"francaise","Tomber dans les pommes","PC","« Tomber dans les pommes » veut dire s'évanouir. Peut-être une déformation de « tomber dans les pâmes ».",null,"https://fr.wiktionary.org/wiki/Tomber_dans_les_pommes","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-tomber-dans-les-pommes.webp"],["Fexpr_avoir_la_flemme",38,"francaise","Avoir la flemme","R","« Avoir la flemme », c'est être trop paresseux pour faire quoi que ce soit. Un état bien connu des étudiants.",null,"https://fr.wiktionary.org/wiki/Avoir_la_flemme","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-la-flemme.webp"],["Fexpr_il_pleut_des_cordes",39,"francaise","Il pleut des cordes","C","« Il pleut des cordes » veut dire qu'il pleut très fort, comme si la pluie tombait en fils continus.",null,"https://fr.wiktionary.org/wiki/Il_pleut_des_cordes","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-il-pleut-des-cordes.webp"],["Fexpr_les_carottes_sont_cuites",40,"francaise","Les carottes sont cuites","PC","« Les carottes sont cuites » veut dire que c'est fini, qu'il n'y a plus rien à faire.",null,"https://fr.wiktionary.org/wiki/Les_carottes_sont_cuites","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-les-carottes-sont-cuites.webp"],["Fexpr_mettre_les_pieds_dans_le_plat",41,"francaise","Mettre les pieds dans le plat","C","« Mettre les pieds dans le plat », c'est aborder un sujet délicat sans aucune délicatesse.",null,"https://fr.wiktionary.org/wiki/Mettre_les_pieds_dans_le_plat","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-mettre-les-pieds-dans-le-plat.webp"],["Fexpr_raconter_des_salades",42,"francaise","Raconter des salades","C","« Raconter des salades » veut dire raconter des mensonges ou des histoires inventées.",null,"https://fr.wiktionary.org/wiki/Raconter_des_salades","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-raconter-des-salades.webp"],["Fexpr_avoir_la_peche",43,"francaise","Avoir la pêche","C","« Avoir la pêche » veut dire être plein d'énergie et de bonne humeur.",null,"https://fr.wiktionary.org/wiki/Avoir_la_pêche","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-la-peche.webp"],["Fexpr_se_prendre_un_rateau",44,"francaise","Se prendre un râteau","PC","« Se prendre un râteau », c'est se faire rejeter quand on tente sa chance en amour.",null,"https://fr.wiktionary.org/wiki/Se_prendre_un_râteau","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-se-prendre-un-rateau.webp"],["Fexpr_faire_la_grasse_matinee",45,"francaise","Faire la grasse matinée","C","« Faire la grasse matinée » veut dire rester au lit tard le matin.",null,"https://fr.wiktionary.org/wiki/Faire_la_grasse_matinée","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-faire-la-grasse-matinee.webp"],["Fexpr_avoir_le_seum",46,"francaise","Avoir le seum","R","« Avoir le seum » (de l'arabe « poison ») veut dire être énervé, dégoûté ou frustré. Un classique de l'argot des années 2010.",112,"https://fr.wiktionary.org/wiki/Avoir_le_seum","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-le-seum.webp"],["Fexpr_chelou",47,"francaise","Chelou","PC","« Chelou » est le verlan de « louche » : quelque chose ou quelqu'un de bizarre.",null,"https://fr.wiktionary.org/wiki/Chelou","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-chelou.webp"],["Fexpr_wesh",48,"francaise","Wesh","R","« Wesh » est une interjection venue de l'arabe algérien, qui sert à saluer ou interpeller : « Wesh, bien ou bien ? »",null,"https://fr.wiktionary.org/wiki/Wesh","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-wesh.webp"],["Fexpr_ca_passe_creme",49,"francaise","Ça passe crème","PC","« Ça passe crème » veut dire que ça passe facilement, sans accroc.",null,"https://fr.wiktionary.org/wiki/Ça_passe_crème","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ca-passe-creme.webp"],["Fexpr_c_est_la_hess",50,"francaise","C'est la hess","PC","« C'est la hess » veut dire qu'on est dans la galère, souvent sans argent.",null,"https://fr.wiktionary.org/wiki/C'est_la_hess","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-c-est-la-hess.webp"],["Fexpr_etre_dans_la_lune",51,"francaise","Être dans la lune","C","« Être dans la lune », c'est être distrait, perdu dans ses pensées.",null,"https://fr.wiktionary.org/wiki/Être_dans_la_lune","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-etre-dans-la-lune.webp"],["Fexpr_avoir_un_poil_dans_la_main",52,"francaise","Avoir un poil dans la main","PC","« Avoir un poil dans la main » veut dire être très paresseux, au point qu'un poil a eu le temps de pousser dans sa main inactive.",114,"https://fr.wiktionary.org/wiki/Avoir_un_poil_dans_la_main","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-un-poil-dans-la-main.webp"],["Fexpr_faire_chou_blanc",53,"francaise","Faire chou blanc","C","« Faire chou blanc » veut dire échouer, revenir bredouille.",null,"https://fr.wiktionary.org/wiki/Faire_chou_blanc","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-faire-chou-blanc.webp"],["Fexpr_mettre_la_main_a_la_pate",54,"francaise","Mettre la main à la pâte","C","« Mettre la main à la pâte », c'est participer soi-même au travail.",null,"https://fr.wiktionary.org/wiki/Mettre_la_main_à_la_pâte","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-mettre-la-main-a-la-pate.webp"],["Fexpr_tirer_les_vers_du_nez",55,"francaise","Tirer les vers du nez","C","« Tirer les vers du nez » à quelqu'un, c'est lui soutirer des informations petit à petit.",null,"https://fr.wiktionary.org/wiki/Tirer_les_vers_du_nez","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-tirer-les-vers-du-nez.webp"],["Fexpr_avoir_d_autres_chats_a_fouetter",56,"francaise","Avoir d'autres chats à fouetter","C","« Avoir d'autres chats à fouetter » veut dire avoir mieux à faire.",null,"https://fr.wiktionary.org/wiki/Avoir_d'autres_chats_à_fouetter","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-d-autres-chats-a-fouetter.webp"],["Fexpr_quand_les_poules_auront_des_dents",57,"francaise","Quand les poules auront des dents","PC","« Quand les poules auront des dents » veut dire : jamais.",null,"https://fr.wiktionary.org/wiki/Quand_les_poules_auront_des_dents","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-quand-les-poules-auront-des-dents.webp"],["Fexpr_les_doigts_dans_le_nez",58,"francaise","Les doigts dans le nez","C","Faire quelque chose « les doigts dans le nez », c'est le réussir très facilement.",null,"https://fr.wiktionary.org/wiki/Les_doigts_dans_le_nez","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-les-doigts-dans-le-nez.webp"],["Fexpr_ca_me_fait_une_belle_jambe",59,"francaise","Ça me fait une belle jambe","C","« Ça me fait une belle jambe » veut dire que ça ne sert à rien, que ça ne nous avance pas.",null,"https://fr.wiktionary.org/wiki/Ça_me_fait_une_belle_jambe","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ca-me-fait-une-belle-jambe.webp"],["Fexpr_la_moutarde_qui_monte_au_nez",60,"francaise","La moutarde qui monte au nez","C","Quand « la moutarde vous monte au nez », vous commencez à vous mettre en colère.",null,"https://fr.wiktionary.org/wiki/La_moutarde_qui_monte_au_nez","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-la-moutarde-qui-monte-au-nez.webp"],["Fexpr_avoir_le_melon",61,"francaise","Avoir le melon","C","« Avoir le melon » veut dire avoir la grosse tête, se croire supérieur.",null,"https://fr.wiktionary.org/wiki/Avoir_le_melon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-le-melon.webp"],["Fexpr_kiffer",62,"francaise","Kiffer","PC","« Kiffer » (de l'arabe « kif », plaisir) veut dire aimer beaucoup, apprécier.",null,"https://fr.wiktionary.org/wiki/Kiffer","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-kiffer.webp"],["Fexpr_daron_daronne",63,"francaise","Daron, daronne","PC","Le « daron » et la « daronne » sont le père et la mère, en argot.",null,"https://fr.wiktionary.org/wiki/Daron,_daronne","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-daron-daronne.webp"],["Fexpr_avoir_la_gueule_de_bois",64,"francaise","Avoir la gueule de bois","C","« Avoir la gueule de bois », c'est subir les lendemains difficiles d'une soirée trop arrosée.",null,"https://fr.wiktionary.org/wiki/Avoir_la_gueule_de_bois","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-avoir-la-gueule-de-bois.webp"],["Fexpr_faire_la_tete",65,"francaise","Faire la tête","C","« Faire la tête » veut dire bouder, être fâché sans le dire.",null,"https://fr.wiktionary.org/wiki/Faire_la_tête","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-faire-la-tete.webp"],["Fexpr_oui_bon",66,"belge","Oui bon !","R","« Oui bon ! » est l'expression fétiche d'aymeric6103 et de Vivian, colocataires à Montignies-sur-Sambre : deux petits mots lâchés d'un ton sec quand quelque chose commence sérieusement à les agacer. Si tu l'entends, c'est le signal qu'il vaut mieux changer de sujet… ou arrêter de les embêter.",110,"https://cgrcfs.github.io/WikiCards-App/","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-oui-bon.webp"],["Fexpr_tchouler",67,"belge","Tchouler","PC","« Tchouler » veut dire pleurer, et même pleurer à chaudes larmes, en Wallonie (Mons, Tournai…) comme dans le Nord de la France : « Arrête de tchouler comme un gamin ! ». Celui qui pleurniche pour un rien, c'est un « tchouleu » ou un « tchoule ».",113,"https://fr.wiktionary.org/wiki/tchouler","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-tchouler.webp"],["Fexpr_ma_hchouma",68,"marocaine","Hchouma","E","« Hchouma » veut dire « la honte » en darija marocaine. C'est LE mot que les parents marocains répètent depuis l'enfance : on ne parle pas fort, on ne s'assoit pas n'importe comment… « Hchouma ! ». Il désigne tout ce qui ne se fait pas.",110,"https://fr.wiktionary.org/wiki/حشومة","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-hchouma.webp"],["Fexpr_ma_inchallah",69,"marocaine","Inchallah","R","« Inchallah » signifie « si Dieu le veut ». Au Maroc, il sert à parler de l'avenir, mais tout le monde sait qu'un « inchallah » de maman en réponse à « on peut aller au parc ? » veut souvent dire… non.",115,"https://fr.wiktionary.org/wiki/إن شاء الله","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-inchallah.webp"],["Fexpr_ma_zaama",70,"marocaine","Zaama","R","« Zaama » veut dire « soi-disant », « genre ». Passé dans l'argot français sous la forme « zarma », il sert à se moquer de quelqu'un qui se la raconte : « Zaama il sait conduire… ».",112,"https://fr.wiktionary.org/wiki/زعما","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-zaama.webp"],["Fexpr_ma_safi",71,"marocaine","Safi","R","« Safi » veut dire « c'est bon », « ça suffit » ou « bon, alors ». C'est le mot passe-partout du darija : on le dit pour clore une discussion, valider un prix ou arrêter une dispute.",115,"https://fr.wiktionary.org/wiki/صافي","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-safi.webp"],["Fexpr_ma_wakha",72,"marocaine","Wakha","R","« Wakha » veut dire « d'accord », « OK » en darija marocaine. Un « wakha » traîné et peu convaincu veut plutôt dire « oui oui, cause toujours ».",115,"https://fr.wiktionary.org/wiki/واخا","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-wakha.webp"],["Fexpr_ma_bsaha",73,"marocaine","Bsaha","R","« Bsaha » (« à ta santé ») se dit au Maroc après un repas, une douche, une coupe de cheveux ou un nouveau vêtement : c'est une façon de souhaiter que ça te profite. On répond « Allah y3tik saha ».",116,"https://fr.wiktionary.org/wiki/بالصحة","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-bsaha.webp"],["Fexpr_ma_daba",74,"marocaine","Daba","PC","« Daba » veut dire « maintenant ». Mais un « daba daba » marocain peut vouloir dire tout de suite… ou dans trois heures.",null,"https://fr.wiktionary.org/wiki/دابا","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-daba.webp"],["Fexpr_ma_tbarkallah",75,"marocaine","Tbarkallah","PC","« Tbarkallah » (« que Dieu bénisse ») accompagne un compliment au Maroc : on le dit devant un bébé, une belle réussite ou une nouvelle voiture, pour éloigner le mauvais œil.",109,"https://fr.wiktionary.org/wiki/تبارك الله","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-tbarkallah.webp"],["Fexpr_ma_wach",76,"marocaine","Wach","PC","« Wach » sert à poser une question en darija : « Wach nta mzyan ? » (« Est-ce que tu vas bien ? »). En France, il est devenu « wesh », la salutation de la rue.",113,"https://fr.wiktionary.org/wiki/واش","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-wach.webp"],["Fexpr_ma_bezzaf",77,"marocaine","Bezzaf","PC","« Bezzaf » veut dire « beaucoup » ou « trop » : « Choukran bezzaf » (« merci beaucoup »), ou « Ghali bezzaf ! » (« c'est beaucoup trop cher ! ») au souk.",114,"https://fr.wiktionary.org/wiki/بزاف","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-bezzaf.webp"],["Fexpr_ma_yallah",78,"marocaine","Yallah","PC","« Yallah » veut dire « allez ! », « on y va ! ». C'est le mot pour presser tout le monde, des grands départs en vacances aux sorties de mariage.",111,"https://fr.wiktionary.org/wiki/يالله","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-yallah.webp"],["Fexpr_ma_labas",79,"marocaine","Labas ?","PC","« Labas ? » veut dire « ça va ? » (littéralement « pas de mal ? »). On répond « labas, hamdoullah » : la base de toute conversation marocaine.",112,"https://fr.wiktionary.org/wiki/لاباس","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-labas.webp"],["Fexpr_ma_mochkil",80,"marocaine","Machi mochkil","PC","« Machi mochkil » veut dire « pas de problème ». C'est la réponse marocaine à presque tout, y compris aux vrais problèmes.",111,"https://fr.wiktionary.org/wiki/ماشي مشكل","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-mochkil.webp"],["Fexpr_ma_hamdoullah",81,"marocaine","Hamdoullah","C","« Hamdoullah » veut dire « Dieu merci ». On le dit pour répondre à « ça va ? », après un repas ou quand on échappe de peu à une catastrophe.",114,"https://fr.wiktionary.org/wiki/الحمد لله","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-hamdoullah.webp"],["Fexpr_ma_choukran",82,"marocaine","Choukran","C","« Choukran » veut dire « merci ». En darija, on dit souvent « choukran bezzaf », « merci beaucoup ».",null,"https://fr.wiktionary.org/wiki/شكرا","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-choukran.webp"],["Fexpr_ma_bslama",83,"marocaine","Bslama","C","« Bslama » veut dire « au revoir » (littéralement « avec la paix »). C'est le mot qu'on lance en partant, souvent répété trois fois sur le pas de la porte.",113,"https://fr.wiktionary.org/wiki/بسلامة","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-bslama.webp"],["Fexpr_ma_merhba",84,"marocaine","Merhba","C","« Merhba » veut dire « bienvenue » ou « avec plaisir ». Au Maroc, l'invité est roi : « merhba bik » accompagne toujours le thé à la menthe.",110,"https://fr.wiktionary.org/wiki/مرحبا","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-merhba.webp"],["Fexpr_ma_zwin",85,"marocaine","Zwin","C","« Zwin » (ou « zwina » au féminin) veut dire « beau », « joli », « bien ». « Zwin bezzaf ! » : c'est trop bien !",null,"https://fr.wiktionary.org/wiki/زوين","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-zwin.webp"],["Fexpr_ma_sahbi",86,"marocaine","Sahbi","C","« Sahbi » veut dire « mon pote », « mon ami ». On l'utilise pour appeler un ami, ou un inconnu qu'on veut amadouer.",null,"https://fr.wiktionary.org/wiki/صاحبي","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-sahbi.webp"],["Fexpr_ma_smeh_liya",87,"marocaine","Smeh liya","C","« Smeh liya » veut dire « pardonne-moi » ou « excuse-moi ». Il sert aussi à se frayer un chemin dans la foule du souk.",null,"https://fr.wiktionary.org/wiki/سمح ليا","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-smeh_liya.webp"],["Fexpr_ma_kidayr",88,"marocaine","Kidayr ?","C","« Kidayr ? » (« kidayra ? » pour une fille) veut dire « comment tu vas ? ». Avec « labas », c'est le début obligatoire de toute discussion.",106,"https://fr.wiktionary.org/wiki/كيداير","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/x-ma-kidayr.webp"]]]);